def _handle_failure(self, job: Job, exc: Exception) -> Job:
    """Выбрать исход упавшей попытки по политике, которая действует в момент ошибки."""
    error = format_error(exc)
    policy = self._queue.retry_policy_for(job.job_type)
    if policy is None:
        return self._queue.mark_failed(job.id, error)
    # причина «неповторяемая» важнее исчерпания попыток, поэтому проверяем её первой
    if not policy.is_retryable(exc):
        logger.warning("%s: job %s failed with a non-retryable error, moving to dead-letter", self.name, job.id)
        return self._queue.mark_dead_lettered(job.id, error, reason=DeadLetterReason.NON_RETRYABLE)
    if job.attempts >= policy.max_attempts:
        logger.warning("%s: job %s is out of attempts, moving to dead-letter", self.name, job.id)
        return self._queue.mark_dead_lettered(job.id, error, reason=DeadLetterReason.EXHAUSTED)

