        # срок назвал внешний сервис: джиттер и rng не применяем, потолок max_delay сохраняем
        delay = min(exc.retry_after, policy.max_delay)
    else:
        delay = policy.delay_for(job.attempts, self._rng)
    run_at = self._queue.clock.now() + timedelta(seconds=delay)

